#include <iostream>
using namespace std;
class Circle {
  private:
    float radius;
  public:
    void GetRadius() {
        cout << "Enter radius of the circle: ";
        cin >> radius;
    }
    void CalArea() {
        float area = 3.14159 * radius * radius;
        cout << "Area of circle = " << area << endl;
    }
};
int main() {
    Circle c;
    c.GetRadius();
    c.CalArea();
    return 0;
}

#include <iostream>
using namespace std;
class Employee {
  protected:
    int id;
    string name;
    float salary;
  public:
    void getEmployee() {
        cout << "Enter ID, name and salary: ";
        cin >> id >> name >> salary;
    }
    void showEmployee() {
        cout << "ID: " << id << "  Name: " << name << "  Salary: " << salary << endl;
    }
};
class Manager : public Employee {
    string department;
  public:
    void getManager() {
        getEmployee();
        cout << "Enter department: ";
        cin >> department;
    }
    void showManager() {
        showEmployee();
        cout << "Department: " << department << endl;
    }
};
int main() {
    Manager m;
    m.getManager();
    m.showManager();
    return 0;
}

#include <iostream>
using namespace std;
class ConstDest {
  public:
    ConstDest() {
        cout << "Constructor called: object created" << endl;
    }
    ~ConstDest() {
        cout << "Destructor called: object destroyed" << endl;
    }
};
int main() {
    ConstDest obj;
    cout << "Inside main()" << endl;
    return 0;
}

#include <iostream>
using namespace std;
class Time {
    int hours, minutes, seconds;
  public:
    Time(int h, int m, int s) {
        hours = h; minutes = m; seconds = s;
    }
    void ToSecond() {
        long total = hours * 3600L + minutes * 60 + seconds;
        cout << hours << ":" << minutes << ":" << seconds << " = " << total << " seconds" << endl;
    }
};
int main() {
    int h, m, s;
    cout << "Enter hours, minutes and seconds: ";
    cin >> h >> m >> s;
    Time t(h, m, s);
    t.ToSecond();
    return 0;
}
